import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    a = []
    idx = 2
    for _ in range(n):
        a.append(int(data[idx]))
        idx += 1

    b = []
    for _ in range(m):
        b.append(int(data[idx]))
        idx += 1

    grid = [['.' for _ in range(m)] for _ in range(n)]

    def count_segments(line):
        cnt = 0
        in_seg = False
        for char in line:
            if char == '*':
                if not in_seg:
                    cnt += 1
                    in_seg = True
            else:
                in_seg = False
        return cnt

    def get_col(col_idx):
        return [grid[r][col_idx] for r in range(n)]

    def set_row(r, val):
        for c in range(m):
            grid[r][c] = val[c]

    def set_col(c, val):
        for r in range(n):
            grid[r][c] = val[r]

    def backtrack(idx):
        if idx == n * m:
            for i in range(n):
                if count_segments(grid[i]) != a[i]:
                    return False
            for j in range(m):
                col_vals = get_col(j)
                if count_segments(col_vals) != b[j]:
                    return False
            return True

        r = idx // m
        c = idx % m

        for char in ['*', '.']:
            grid[r][c] = char

            if backtrack(idx + 1):
                return True

        grid[r][c] = '.'
        return False

    backtrack(0)

    for row in grid:
        print(''.join(row))

if __name__ == "__main__":
    solve()
